"""Lay students out in rows by last name."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def sort_key(student: Student) -> tuple:
    """Order by last name, then first name, ignoring case."""
    return (student.last_name.lower(), student.first_name.lower())


def seating_rows(students: List[Student], seats_per_row: int) -> List[str]:
    """One line per row, like 'Row 1: Dunmere, Piet | Halloway, Juno'."""
    if seats_per_row <= 0:
        raise ProjectError("seats per row must be positive")
    if not students:
        raise ProjectError("no students to seat")
    ordered = sorted(students, key=sort_key)
    lines = []
    # step through the sorted students one row at a time
    for start in range(0, len(ordered), seats_per_row):
        names = [s.display_name for s in ordered[start:start + seats_per_row]]
        lines.append(f"Row {start // seats_per_row + 1}: " + " | ".join(names))
    return lines

